  function decoratePalette(){$$('.pitem').forEach(function(el){var t=el.getAttribute('data-add');if(!t||el.querySelector('.pisvg'))return;el.insertAdjacentHTML('afterbegin','<span class="pisvg">'+iconSVG(PAL_ICON[t]||'sensor')+'</span>');});}
  // Adaptive Icons: verändern ihr Aussehen anhand eines gebundenen Wertes (0–100 % bzw. Zustand).
  function aiPct(v){if(v==null)return 100;var n=parseFloat(String(v).replace(',','.'));if(isNaN(n))n=(v===true||v==='1'||v==='true'||v==='on')?100:0;return Math.max(0,Math.min(100,n));}
  function aiState(v){if(v==null)return 0;var s=String(v).toLowerCase().trim();
    if(s==='2'||s==='tilt'||s.indexOf('kipp')>=0)return 1;
    if(s==='1'||s==='true'||s==='open'||s==='offen'||s==='auf'||s==='on')return 2;
    if(s==='0'||s==='false'||s==='closed'||s==='zu'||s==='geschlossen'||s==='off')return 0;
    var n=parseFloat(s.replace(',','.'));if(!isNaN(n))return n<=0?0:(n>=2?2:1);return 0;}
  function aiClamp(p){p=parseFloat(p);return isNaN(p)?0:Math.max(0,Math.min(100,p));}
  function aiOp(p){return (0.12+aiClamp(p)/100*0.78).toFixed(2);}
  function aiVfill(x,y,w,h,p){var fh=h*aiClamp(p)/100;return fh<0.4?'':'<rect x="'+x+'" y="'+(y+h-fh).toFixed(1)+'" width="'+w+'" height="'+fh.toFixed(1)+'" rx="1" fill="currentColor" stroke="none" opacity=".8"/>';}
  function aiHfill(x,y,w,h,p,op){var fw=w*aiClamp(p)/100;return fw<0.4?'':'<rect x="'+x+'" y="'+y+'" width="'+fw.toFixed(1)+'" height="'+h+'" rx="1" fill="currentColor" stroke="none" opacity="'+(op||1)+'"/>';}
